import{_ as n,a0 as p,w as d,s as o,ao as h,I as l,x as i,a1 as a,A as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const y=JSON.parse('{"title":"如何使用 Vim 編輯多個文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何使用 Vim 編輯多個文件 | LCTT (201805) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何使用 Vim 編輯多個文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何使用 Vim 編輯多個文件 | LCTT (201805) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201805/20180317 How To Edit Multiple Files Using Vim Editor","title":"如何使用 Vim 編輯多個文件","tag":"201805","desc":""},"relativePath":"201805/20180317 How To Edit Multiple Files Using Vim Editor.md","filePath":"[post].md"}'),c={name:"201805/20180317 How To Edit Multiple Files Using Vim Editor.md"};function g(r,s,k,b,u,f){const e=p("Link");return d(),o("div",null,[s[13]||(s[13]=h(`<h1 id="如何使用-vim-編輯多個文件" tabindex="-1">如何使用 Vim 編輯多個文件 <a class="header-anchor" href="#如何使用-vim-編輯多個文件" aria-label="Permalink to “如何使用 Vim 編輯多個文件”">​</a></h1><p><img src="https://www.ostechnix.com/wp-content/uploads/2018/03/Edit-Multiple-Files-Using-Vim-Editor-720x340.png" alt=""></p><p>有時候，您可能需要修改多個文件，或要將一個文件的內容複製到另一個文件中。在圖形用户界面中，您可以在任何圖形文本編輯器（如 gedit）中打開文件，並使用 <code>CTRL + C</code> 和 <code>CTRL + V</code> 複製和粘貼內容。在命令列模式下，您不能使用這種編輯器。不過別擔心，只要有 <code>vim</code> 編輯器就有辦法。在本教程中，我們將學習使用 <code>vim</code> 編輯器同時編輯多個文件。相信我，很有意思噠。</p><h3 id="安裝-vim" tabindex="-1">安裝 Vim <a class="header-anchor" href="#安裝-vim" aria-label="Permalink to “安裝 Vim”">​</a></h3><p>Vim 編輯器可在大多數 Linux 發行版的官方軟件倉庫中找到，所以您可以用默認的軟件包管理器來安裝它。例如，在 Arch Linux 及其變體上，您可以使用如下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo pacman -S vim</span></span></code></pre></div><p>在 Debian 和 Ubuntu 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo apt-get install vim</span></span></code></pre></div><p>在 RHEL 和 CentOS 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo yum install vim</span></span></code></pre></div><p>在 Fedora 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install vim</span></span></code></pre></div><p>在 openSUSE 上：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo zypper install vim</span></span></code></pre></div><h3 id="使用-linux-的-vim-編輯器同時編輯多個文件" tabindex="-1">使用 Linux 的 Vim 編輯器同時編輯多個文件 <a class="header-anchor" href="#使用-linux-的-vim-編輯器同時編輯多個文件" aria-label="Permalink to “使用 Linux 的 Vim 編輯器同時編輯多個文件”">​</a></h3><p>現在讓我們談談正事，我們可以用兩種方法做到這一點。</p><h4 id="方法一" tabindex="-1">方法一 <a class="header-anchor" href="#方法一" aria-label="Permalink to “方法一”">​</a></h4><p>有兩個文件，即 <code>file1.txt</code> 和 <code>file2.txt</code>，帶有一堆隨機單詞：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat file1.txt</span></span>
<span class="line"><span>ostechnix</span></span>
<span class="line"><span>open source</span></span>
<span class="line"><span>technology</span></span>
<span class="line"><span>linux</span></span>
<span class="line"><span>unix</span></span>
<span class="line"><span></span></span>
<span class="line"><span>$ cat file2.txt</span></span>
<span class="line"><span>line1</span></span>
<span class="line"><span>line2</span></span>
<span class="line"><span>line3</span></span>
<span class="line"><span>line4</span></span>
<span class="line"><span>line5</span></span></code></pre></div><p>現在，讓我們同時編輯這兩個文件。請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim file1.txt file2.txt</span></span></code></pre></div><p>Vim 將按順序顯示文件的內容。首先顯示第一個文件的內容，然後顯示第二個文件，依此類推。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-1-1.png" alt=""></p><h5 id="在文件中切換" tabindex="-1">在文件中切換 <a class="header-anchor" href="#在文件中切換" aria-label="Permalink to “在文件中切換”">​</a></h5><p>要移至下一個文件，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:n</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-2.png" alt=""></p><p>要返回到前一個文件，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:N</span></span></code></pre></div><p>如果有任何未保存的更改，Vim 將不允許您移動到下一個文件。要保存當前文件中的更改，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZZ</span></span></code></pre></div><p>請注意，是兩個大寫字母 <code>ZZ</code>（<code>SHIFT + zz</code>）。</p><p>要放棄更改並移至上一個文件，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:N!</span></span></code></pre></div><p>要查看當前正在編輯的文件，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffers</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-5.png" alt=""></p><p>您將在底部看到加載文件的列表。</p><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-6.png" alt=""></p><p>要切換到下一個文件，請輸入 <code>:buffer</code>，後跟緩衝區編號。例如，要切換到第一個文件，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 1</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-7.png" alt=""></p><h5 id="打開其他文件進行編輯" tabindex="-1">打開其他文件進行編輯 <a class="header-anchor" href="#打開其他文件進行編輯" aria-label="Permalink to “打開其他文件進行編輯”">​</a></h5><p>目前我們正在編輯兩個文件，即 <code>file1.txt</code> 和 <code>file2.txt</code>。我想打開另一個名為 <code>file3.txt</code> 的文件進行編輯。</p><p>您會怎麼做？這很容易。只需鍵入 <code>:e</code>，然後輸入如下所示的文件名即可：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:e file3.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-8.png" alt=""></p><p>現在你可以編輯 <code>file3.txt</code> 了。</p><p>要查看當前正在編輯的文件數量，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffers</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-10-1.png" alt=""></p><p>請注意，對於使用 <code>:e</code> 打開的文件，您無法使用 <code>:n</code> 或 <code>:N</code> 進行切換。要切換到另一個文件，請輸入 <code>:buffer</code>，然後輸入文件緩衝區編號。</p><h5 id="將一個文件的內容複製到另一個文件中" tabindex="-1">將一個文件的內容複製到另一個文件中 <a class="header-anchor" href="#將一個文件的內容複製到另一個文件中" aria-label="Permalink to “將一個文件的內容複製到另一個文件中”">​</a></h5><p>您已經知道了如何同時打開和編輯多個文件。有時，您可能想要將一個文件的內容複製到另一個文件中。這也是可以做到的。切換到您選擇的文件，例如，假設您想將 <code>file1.txt</code> 的內容複製到 <code>file2.txt</code> 中：</p><p>首先，請切換到 <code>file1.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 1</span></span></code></pre></div><p>將光標移動至在想要複製的行的前面，並鍵入<code>yy</code> 以抽出（複製）該行。然後，移至 <code>file2.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 2</span></span></code></pre></div><p>將光標移至要從 <code>file1.txt</code> 粘貼複製行的位置，然後鍵入 <code>p</code>。例如，您想要將複製的行粘貼到 <code>line2</code> 和 <code>line3</code> 之間，請將鼠標光標置於行前並鍵入 <code>p</code>。</p><p>輸出示例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line1</span></span>
<span class="line"><span>line2</span></span>
<span class="line"><span>ostechnix</span></span>
<span class="line"><span>line3</span></span>
<span class="line"><span>line4</span></span>
<span class="line"><span>line5</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-11.png" alt=""></p><p>要保存當前文件中所做的更改，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZZ</span></span></code></pre></div><p>再次提醒，是兩個大寫字母 ZZ（<code>SHIFT + z</code>）。</p><p>保存所有文件的更改並退出 vim 編輯器，鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:wq</span></span></code></pre></div><p>同樣，您可以將任何文件的任何行復制到其他文件中。</p><h5 id="將整個文件內容複製到另一個文件中" tabindex="-1">將整個文件內容複製到另一個文件中 <a class="header-anchor" href="#將整個文件內容複製到另一個文件中" aria-label="Permalink to “將整個文件內容複製到另一個文件中”">​</a></h5><p>我們知道如何複製一行，那麼整個文件的內容呢？也是可以的。比如説，您要將 <code>file1.txt</code> 的全部內容複製到 <code>file2.txt</code> 中。</p><p>先打開 <code>file2.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim file2.txt</span></span></code></pre></div><p>如果文件已經加載，您可以通過輸入以下命令切換到 <code>file2.txt</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 2</span></span></code></pre></div><p>將光標移動到您想要粘貼 <code>file1.txt</code> 的內容的位置。我想在 <code>file2.txt</code> 的第 5 行之後粘貼 <code>file1.txt</code> 的內容，所以我將光標移動到第 5 行。然後，鍵入以下命令並按回車鍵：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:r file1.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-12.png" alt=""></p><p>這裏，<code>r</code> 代表 “read”。</p><p>現在您會看到 <code>file1.txt</code> 的內容被粘貼在 <code>file2.txt</code> 的第 5 行之後。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>line1</span></span>
<span class="line"><span>line2</span></span>
<span class="line"><span>line3</span></span>
<span class="line"><span>line4</span></span>
<span class="line"><span>line5</span></span>
<span class="line"><span>ostechnix</span></span>
<span class="line"><span>open source</span></span>
<span class="line"><span>technology</span></span>
<span class="line"><span>linux</span></span>
<span class="line"><span>unix</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/edit-multiple-files-13.png" alt=""></p><p>要保存當前文件中的更改，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ZZ</span></span></code></pre></div><p>要保存所有文件的所有更改並退出 vim 編輯器，請輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:wq</span></span></code></pre></div><h4 id="方法二" tabindex="-1">方法二 <a class="header-anchor" href="#方法二" aria-label="Permalink to “方法二”">​</a></h4><p>另一種同時打開多個文件的方法是使用 <code>-o</code> 或 <code>-O</code> 標誌。</p><p>要在水平窗口中打開多個文件，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim -o file1.txt file2.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Edit-multiple-files-16.png" alt=""></p><p>要在窗口之間切換，請按 <code>CTRL-w w</code>（即按 <code>CTRL + w</code> 並再次按 <code>w</code>）。或者，您可以使用以下快捷方式在窗口之間移動：</p><ul><li><code>CTRL-w k</code> – 上面的窗口</li><li><code>CTRL-w j</code> – 下面的窗口</li></ul><p>要在垂直窗口中打開多個文件，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ vim -O file1.txt file2.txt file3.txt</span></span></code></pre></div><p><img src="http://www.ostechnix.com/wp-content/uploads/2018/03/Edit-multiple-files-17.png" alt=""></p><p>要在窗口之間切換，請按 <code>CTRL-w w</code>（即按 <code>CTRL + w</code> 並再次按 <code>w</code>）。或者，使用以下快捷方式在窗口之間移動：</p><ul><li><code>CTRL-w l</code> – 左面的窗口</li><li><code>CTRL-w h</code> – 右面的窗口</li></ul><p>其他的一切都與方法一的描述相同。</p><p>例如，要列出當前加載的文件，請運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffers</span></span></code></pre></div><p>在文件之間切換：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:buffer 1</span></span></code></pre></div><p>打開其他文件，請鍵入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:e file3.txt</span></span></code></pre></div><p>將文件的全部內容複製到另一個文件中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>:r file1.txt</span></span></code></pre></div><p>方法二的唯一區別是，只要您使用 <code>ZZ</code> 保存對當前文件的更改，文件將自動關閉。然後，您需要依次鍵入 <code>:wq</code> 來關閉文件。但是，如果您按照方法一進行操作，輸入 <code>:wq</code> 時，所有更改將保存在所有文件中，並且所有文件將立即關閉。</p><p>有關更多詳細信息，請參閲手冊頁。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ man vim</span></span></code></pre></div><h3 id="建議閲讀" tabindex="-1">建議閲讀 <a class="header-anchor" href="#建議閲讀" aria-label="Permalink to “建議閲讀”">​</a></h3><p>您現在掌握瞭如何在 Linux 中使用 vim 編輯器編輯多個文件。正如您所見，編輯多個文件並不難。Vim 編輯器還有更強大的功能。我們接下來會提供更多關於 Vim 編輯器的內容。</p><p>再見！</p><hr>`,113)),l("p",null,[s[1]||(s[1]=i("via: ",-1)),a(e,{href:"https://www.ostechnix.com/how-to-edit-multiple-files-using-vim-editor/"},{default:t(()=>[...s[0]||(s[0]=[i("https://www.ostechnix.com/how-to-edit-multiple-files-using-vim-editor/",-1)])]),_:1})]),l("p",null,[s[5]||(s[5]=i("作者：",-1)),a(e,{href:"https://www.ostechnix.com/author/sk/"},{default:t(()=>[...s[2]||(s[2]=[i("SK",-1)])]),_:1}),s[6]||(s[6]=i(" 譯者：",-1)),a(e,{href:"https://github.com/jessie-pang"},{default:t(()=>[...s[3]||(s[3]=[i("jessie-pang",-1)])]),_:1}),s[7]||(s[7]=i(" 校對：",-1)),a(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[4]||(s[4]=[i("wxy",-1)])]),_:1})]),l("p",null,[s[10]||(s[10]=i("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[8]||(s[8]=[i("LCTT",-1)])]),_:1}),s[11]||(s[11]=i(" 原創編譯，",-1)),a(e,{href:"https://linux.cn/"},{default:t(()=>[...s[9]||(s[9]=[i("Linux中國",-1)])]),_:1}),s[12]||(s[12]=i(" 榮譽推出",-1))])])}const C=n(c,[["render",g]]);export{y as __pageData,C as default};
